use crate::circuit::{Op,OperationType,QubitId};use sha3::{Digest,Sha3_256};
pub(super)const IDENTITY_NONCE:u64=221;
pub(super)fn run(mut ops:Vec<Op>)->Vec<Op>{assert_eq!(ops.len(),10548821,"Complete exact officiala4ee parent");let mut h=Sha3_256::new();for o in &ops{for v in[o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{h.update(v.to_le_bytes());}}assert_eq!(format!("{:x}",h.finalize()),"2912b0e53cb7d142c3271f11812cad03ecb6272bd5dee3886938ad8fb614f734","Every complete official parent record");
let end=ops.len()-96;for(bit,pair)in ops[end..].chunks_exact(2).enumerate(){for o in pair{assert_eq!(o.kind,OperationType::X);assert_eq!(o.q_target.0,(8u64>>bit)&1);}}ops.truncate(end);let mut ops=super::breakthrough_generic::run(super::context_lease_cache::run(ops));assert!(IDENTITY_NONCE<(1u64<<48));for bit in 0..48{let mut o=Op::empty();o.kind=OperationType::X;o.q_target=QubitId((IDENTITY_NONCE>>bit)&1);o.validate();ops.extend([o,o]);}ops}
